package com.forgeci.api;
import com.forgeci.application.repository.RepositoryService; import java.util.*; import jakarta.validation.*; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/organizations/{organizationId}/repositories") public class RepositoryController { private final RepositoryService service; public RepositoryController(RepositoryService s){service=s;} @GetMapping List<Response> list(Authentication a,@PathVariable UUID organizationId){return service.list(uid(a),organizationId).stream().map(Response::from).toList();} @PostMapping ResponseEntity<Response> connect(Authentication a,@PathVariable UUID organizationId,@Valid @RequestBody ConnectRequest r)throws Exception{return ResponseEntity.status(HttpStatus.CREATED).body(Response.from(service.connect(uid(a),organizationId,r.externalId())));} @DeleteMapping("/{repositoryId}") ResponseEntity<Void> disconnect(Authentication a,@PathVariable UUID organizationId,@PathVariable UUID repositoryId){service.disconnect(uid(a),organizationId,repositoryId);return ResponseEntity.noContent().build();} @PostMapping("/{repositoryId}/refresh") Response<Response> refresh(Authentication a,@PathVariable UUID organizationId,@PathVariable UUID repositoryId)throws Exception{return Response.from(service.refresh(uid(a),organizationId,repositoryId));} private UUID uid(Authentication a){return UUID.fromString(a.getName());} record ConnectRequest(@NotBlank String externalId){} record Response(UUID id,UUID organizationId,String provider,String externalId,String name,String fullName,String cloneUrl,String defaultBranch,boolean privateRepository){static Response from(com.forgeci.domain.repository.Repository r){return new Response(r.getId(),r.getOrganization().getId(),r.getProvider().name(),r.getExternalId(),r.getName(),r.getFullName(),r.getCloneUrl(),r.getDefaultBranch(),r.isPrivateRepository());}} }
